package com.example.repairreports;
import android.app.*;import android.os.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.graphics.Color;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;
public class MainActivity extends Activity {
 DB db; LinearLayout root,list; EditText search; int blue=Color.rgb(21,101,192),pad=18;
 public void onCreate(Bundle b){super.onCreate(b);getWindow().getDecorView().setLayoutDirection(View.LAYOUT_DIRECTION_RTL);db=new DB(this);home();}
 TextView tv(String s,int sp){TextView t=new TextView(this);t.setText(s);t.setTextSize(sp);t.setTextColor(Color.DKGRAY);t.setPadding(pad,10,pad,10);return t;} Button btn(String s){Button b=new Button(this);b.setText(s);return b;}
 void base(String title){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(245,247,250));TextView h=tv(title,22);h.setTextColor(blue);h.setGravity(Gravity.CENTER);h.setTypeface(null,1);root.addView(h,new LinearLayout.LayoutParams(-1,70));setContentView(root);}
 void home(){base("گزارش کار تعمیرات");LinearLayout bar=new LinearLayout(this);bar.setPadding(10,0,10,5);search=new EditText(this);search.setHint("جست‌وجو: مدل، خطا، مشتری...");Button add=btn("+ گزارش جدید");bar.addView(search,new LinearLayout.LayoutParams(0,60,1));bar.addView(add,new LinearLayout.LayoutParams(125,60));root.addView(bar);add.setOnClickListener(v->form(null));list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);ScrollView sv=new ScrollView(this);sv.addView(list);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int d){}public void onTextChanged(CharSequence s,int a,int b,int c){load(s.toString());}public void afterTextChanged(android.text.Editable e){}});load("");}
 void load(String q){list.removeAllViews();Cursor c=db.search(q);int n=0;while(c.moveToNext()){n++;final long id=c.getLong(0);LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setBackgroundColor(Color.WHITE);card.addView(tv(c.getString(2)+"  |  "+c.getString(3),18));card.addView(tv("مشتری: "+nz(c.getString(1))+"   •   تاریخ: "+nz(c.getString(4)),13));card.addView(tv("خرابی: "+nz(c.getString(5)),14));card.setPadding(4,5,4,5);card.setOnClickListener(v->detail(id));list.addView(card,new LinearLayout.LayoutParams(-1,110));}if(n==0)list.addView(tv("هنوز گزارشی ثبت نشده است.",16));c.close();}
 String nz(String s){return s==null?"":s;} EditText field(LinearLayout p,String hint){EditText e=new EditText(this);e.setHint(hint);e.setTextSize(15);e.setPadding(16,8,16,8);p.addView(e,new LinearLayout.LayoutParams(-1,62));return e;}
 void form(Long id){base(id==null?"ثبت گزارش جدید":"ویرایش گزارش");ScrollView sv=new ScrollView(this);LinearLayout f=new LinearLayout(this);f.setOrientation(LinearLayout.VERTICAL);f.setPadding(14,5,14,20);sv.addView(f);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));EditText customer=field(f,"مشتری / محل"),device=field(f,"دستگاه"),model=field(f,"مدل دستگاه"),fault=field(f,"نوع خرابی / کد خطا"),desc=field(f,"شرح مشکل"),action=field(f,"عیب‌یابی و اقدامات انجام‌شده"),part=field(f,"قطعه تعویض‌شده"),result=field(f,"نتیجه تعمیر"),cost=field(f,"هزینه"),status=field(f,"وضعیت (در انتظار / تعمیر / تحویل)");EditText date=field(f,"تاریخ");date.setText(new SimpleDateFormat("yyyy/MM/dd",Locale.US).format(new Date()));if(id!=null){Cursor c=db.one(id);if(c.moveToFirst()){customer.setText(c.getString(1));device.setText(c.getString(2));model.setText(c.getString(3));date.setText(c.getString(4));fault.setText(c.getString(5));desc.setText(c.getString(6));action.setText(c.getString(7));part.setText(c.getString(8));result.setText(c.getString(9));cost.setText(c.getString(10));status.setText(c.getString(11));}c.close();}Button save=btn("ذخیره گزارش");f.addView(save);save.setOnClickListener(v->{if(model.getText().toString().trim().isEmpty()&&device.getText().toString().trim().isEmpty()){Toast.makeText(this,"حداقل دستگاه یا مدل را وارد کنید",Toast.LENGTH_SHORT).show();return;}db.save(id,customer,device,model,date,fault,desc,action,part,result,cost,status);home();Toast.makeText(this,"گزارش ذخیره شد",Toast.LENGTH_SHORT).show();});}
 void detail(long id){Cursor c=db.one(id);if(!c.moveToFirst())return;base("جزئیات گزارش");LinearLayout p=new LinearLayout(this);p.setOrientation(LinearLayout.VERTICAL);ScrollView sv=new ScrollView(this);sv.addView(p);root.addView(sv,new LinearLayout.LayoutParams(-1,0,1));String[] labs={"مشتری / محل","دستگاه","مدل","تاریخ","خرابی / کد خطا","شرح مشکل","اقدامات","قطعه","نتیجه","هزینه","وضعیت"};for(int i=1;i<=11;i++){TextView x=tv(labs[i-1]+": "+nz(c.getString(i)),15);x.setBackgroundColor(Color.WHITE);p.addView(x,new LinearLayout.LayoutParams(-1,-2));}c.close();Button edit=btn("ویرایش");Button del=btn("حذف گزارش");p.addView(edit);p.addView(del);edit.setOnClickListener(v->form(id));del.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("حذف گزارش").setMessage("این گزارش حذف شود؟").setNegativeButton("لغو",null).setPositiveButton("حذف",(d,w)->{db.delete(id);home();}).show());}
 static class DB extends SQLiteOpenHelper{DB(Context c){super(c,"reports.db",null,1);}public void onCreate(SQLiteDatabase x){x.execSQL("CREATE TABLE reports(id INTEGER PRIMARY KEY AUTOINCREMENT,customer TEXT,device TEXT,model TEXT,date TEXT,fault TEXT,description TEXT,actions TEXT,part TEXT,result TEXT,cost TEXT,status TEXT)");}public void onUpgrade(SQLiteDatabase x,int a,int b){}Cursor search(String q){String z="%"+q+"%";return getReadableDatabase().rawQuery("SELECT * FROM reports WHERE customer LIKE ? OR device LIKE ? OR model LIKE ? OR fault LIKE ? OR description LIKE ? OR actions LIKE ? ORDER BY id DESC",new String[]{z,z,z,z,z,z});}Cursor one(long id){return getReadableDatabase().rawQuery("SELECT * FROM reports WHERE id=?",new String[]{""+id});}void save(Long id,EditText...e){ContentValues v=new ContentValues();String[] a={"customer","device","model","date","fault","description","actions","part","result","cost","status"};for(int i=0;i<a.length;i++)v.put(a[i],e[i].getText().toString());if(id==null)getWritableDatabase().insert("reports",null,v);else getWritableDatabase().update("reports",v,"id=?",new String[]{""+id});}void delete(long id){getWritableDatabase().delete("reports","id=?",new String[]{""+id});}}
}
